sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        // get sys property of base SWB URI
        var env = gs.getProperty('x_hsb11_hsbcmss_sw.swb_url');
        var swbToken = gs.getProperty('x_hsb11_hsbcmss_sw.hsbcmss_swb_api_token');
        //populate variables
        var sn_taskid = current.servicenow_task_id,
            qtrack_id = current.qtrack_id.toString(),
            receiveAt = current.receive_at.toString(),
            category = "";
        // conditions for categories
        var recip = current.recipientemail.toLowerCase();
		//Get emails of cash equities and settlement equities from system properties
		//MSS-RBXCE-743
        var cash_equities_emails = gs.getProperty('x_hsb11_hsbcmss_sw.cash_equity_emails').toLowerCase();
        var sttlment_equities_email = gs.getProperty('x_hsb11_hsbcmss_sw.settlement_equity_email').toLowerCase();

        if (cash_equities_emails.contains(recip))
            category = "cashEquity_HK_TradeCaptureAllocation";
        else if (current.recipientemail == sttlment_equities_email)
            category = "cashEquity_HK_Settlements";
        else
            category = "not found";

        var recipient = current.recipientemail,
            sender = current.senderemail,
            attachArr = [],
            attachments = {};
        if (current.email_attachments != "" && current.email_attachments != "[]") {
            attachments = JSON.parse(current.email_attachments);
            for (var i = 0; i < attachments.length; i++) {
                var att64 = attachments[i].Email_Attachment_Content;
                var legacyid = attachments[i].Email_Attachment_Id;
                var att_name = attachments[i].Email_Attachment_Name;
                var attObj = {
                    "attachmentFileName": att_name,
                    "attachmentFileContent": att64,
                    "attachmentId": legacyid
                };
                attachArr.push(attObj);
            }
        }

        var subject = current.email_subject.toString();
        var email_body = current.email_body.toString();
        var r = new sn_ws.RESTMessageV2('HSBC SWB API', 'Extract Email');
        r.setStringParameterNoEscape('swb_base_uri', env);
        r.setStringParameterNoEscape('swb_token', swbToken);
        r.setStringParameterNoEscape('qtrack', qtrack_id);
        r.setStringParameterNoEscape('receiveAt', receiveAt);
        r.setStringParameterNoEscape('recipientemail', recipient);
        r.setStringParameterNoEscape('senderemail', sender);
        r.setStringParameterNoEscape('emailbody', JSON.stringify(email_body));
        r.setStringParameterNoEscape('process_category', category);
        if (attachArr.length < 1)
            r.setStringParameterNoEscape('att_arr', "[]");
        else
            r.setStringParameterNoEscape('att_arr', JSON.stringify(attachArr));

        r.setStringParameterNoEscape('emailsubject', JSON.stringify(subject));
        current.state = 'Processing';
        current.request_date = new GlideDateTime();
        current.setWorkflow(false);
        current.update();
        current.setWorkflow(true);

        var response = r.executeAsync();
        var responseBody = response.getBody();
        var httpStatus = response.getStatusCode();
        var resp_parsed = JSON.parse(responseBody);

        if (httpStatus == '202' || httpStatus == '200') {
            current.response_body = responseBody;
            current.response_code = httpStatus;
            current.swb_id = resp_parsed.swbId;
            current.response_date = new GlideDateTime();
            current.state = "Processed";
        } else {
            current.response_code = httpStatus;
            current.error_body = responseBody;
            current.error_code = resp_parsed.status;
            current.response_message = response.getErrorMessage();
            current.state = 'Error';
        }
        current.response_date = new GlideDateTime();
        current.update();
    } catch (err) {
        gs.info("Business Rule Error: mss.swb.send.to.swb" + err.message);
    }
})(current, previous);
